FEW-SHOT EXAMPLES:

Example 1 (Partial / Compound):
Claim: "Company X's revenue doubled in 2024 to $10M, and it opened 5 new offices."
Reference [S1]: "Company X reported 2024 revenue of $10M, up from $5M in 2023."
Output:
{
  "summary": "One claim is supported by S1; the office expansion claim lacks evidence.",
  "claims": [
    {
      "claimId": "C1",
      "claimText": "Company X's revenue doubled in 2024 to $10M.",
      "verdict": "Supported",
      "explanation": "S1 states 2024 revenue was $10M, up from $5M in 2023 (a 2x increase).",
      "citations": [{ "sourceId": "S1", "quote": "Company X reported 2024 revenue of $10M, up from $5M in 2023." }]
    },
    {
      "claimId": "C2",
      "claimText": "Company X opened 5 new offices in 2024.",
      "verdict": "Insufficient Evidence",
      "explanation": "S1 makes no mention of office openings.",
      "citations": [],
      "missingInformation": "No reference to office openings in any supplied source.",
      "requiredEvidence": "A source explicitly confirming the number and year of office openings."
    }
  ]
}

Example 2 (Ambiguous Identity — role without a name):
Claim: "did the regional governor resign"
Reference [S1]: "our regional head stepped down last week"
Output:
{
  "summary": "Insufficient evidence: S1 uses an ambiguous descriptor without naming the person, region, country, or date.",
  "claims": [
    {
      "claimId": "C1",
      "claimText": "The regional governor resigned.",
      "verdict": "Insufficient Evidence",
      "explanation": "S1 refers only to 'our regional head' without naming the person, specifying the region, country, or providing a date. This ambiguity prevents confirming or contradicting the claim about a specific governor.",
      "citations": [{ "sourceId": "S1", "quote": "our regional head stepped down last week" }],
      "missingInformation": "S1 does not name the person, the specific region, the country, or the exact date.",
      "requiredEvidence": "A source explicitly naming the governor, their region, and confirming or denying the resignation with a date."
    }
  ]
}

Example 3 (Conflicting Sources — do NOT collapse to Contradicted):
Claim: "The merger was completed successfully with no regulatory objections."
Reference [S1 — Company announcement]: "GlobalCorp and MegaTech announced today that their merger has been completed successfully."
Reference [S2 — Regulator statement]: "The Competition Authority has formally raised objections to the GlobalCorp–MegaTech merger and is conducting a Phase 2 investigation."
Output:
{
  "summary": "Conflicting evidence: S1 (company announcement) supports the claim; S2 (regulator statement) directly contradicts the 'no regulatory objections' sub-claim.",
  "claims": [
    {
      "claimId": "C1",
      "claimText": "The GlobalCorp–MegaTech merger was completed successfully.",
      "verdict": "Conflicting Evidence",
      "explanation": "S1 states the merger was completed successfully, while S2 states the Competition Authority raised formal objections and launched a Phase 2 investigation. These sources conflict — one asserts completion and the other asserts regulatory challenge.",
      "citations": [
        { "sourceId": "S1", "quote": "their merger has been completed successfully" },
        { "sourceId": "S2", "quote": "has formally raised objections to the GlobalCorp–MegaTech merger" }
      ]
    }
  ]
}

